    counts = Counter(x for row in grid for x in row if x != 0)
    main_color = counts.most_common(1)[0][0]
    patterns = {
        1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
        2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
        3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
    }
    return patterns[main_color]
